import "server-only";

/* ---------------------------------------------------------------------------
   assets/doc-fonts — the fonts the AI document renderer carries with it.

   WHY EMBEDDED: Vercel's serverless Chromium ships with NO Arabic and NO
   CJK glyphs — a generated Arabic document rendered there came back with
   the Arabic text invisible (owner's first live PDF, 2026-10-08). The
   render contract says "no external assets, no fetch to hang on", so the
   fonts ride INSIDE the bundle as base64.

   · Tajawal (Regular + Bold) — Arabic + Latin, OFL, © 2017 Boutros
     International. Always embedded: 120 KB, so an Arabic sentence inside
     an English document also renders.
   · Noto Sans SC (Regular only) — Simplified Chinese, OFL, © Adobe /
     Google. Embedded ONLY for lang=zh documents (4.7 MB of base64);
     bold is synthesized by the renderer from Regular.
   --------------------------------------------------------------------------- */

export const TAJAWAL_REGULAR_B64 = "";

export const TAJAWAL_BOLD_B64 = "";

export const NOTO_SANS_SC_REGULAR_B64 = "";
